const rows = $input.all().map(i => i.json || {}).filter(r => Object.keys(r).length > 0);
const cfg = $items('Configure SLA Monitoring')[0]?.json || {};

const str = v => v === null || v === undefined ? '' : String(v).trim();
const num = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};
const truthy = v => {
  if (typeof v === 'boolean') return v;
  return ['true','1','yes','y','on','active'].includes(str(v).toLowerCase());
};
const dateValue = v => {
  const d = new Date(String(v || ''));
  return Number.isNaN(d.getTime()) ? 0 : d.getTime();
};

const rules = rows.filter(r => r.rule_id || (r.sla_target !== undefined && r.comparison_type));
const performance = rows.filter(r => r.record_id || (r.actual_value !== undefined && r.measurement_date));
const history = rows.filter(r => r.breach_id || r.breach_key);

const result = [];

for (const rule of rules) {
  if (rule.active !== undefined && !truthy(rule.active)) continue;

  const supplierId = str(rule.supplier_id);
  const metric = str(rule.metric_type).toLowerCase();

  const matches = performance
    .filter(p => str(p.supplier_id) === supplierId && str(p.metric_type).toLowerCase() === metric)
    .sort((a,b) => dateValue(b.measurement_date) - dateValue(a.measurement_date));

  const latest = matches[0];
  if (!latest) {
    result.push({
      json: {
        run_id: cfg.cfg_run_id,
        checked_at: cfg.cfg_checked_at,
        rule_id: str(rule.rule_id),
        supplier_id: supplierId,
        supplier_name: str(rule.supplier_name),
        metric_type: metric,
        data_status: 'missing_performance',
        has_performance: false,
        sla_target: num(rule.sla_target),
        unit: str(rule.unit),
        comparison_type: str(rule.comparison_type).toLowerCase(),
        penalty_clause: str(rule.penalty_clause),
        penalty_rate_pct: num(rule.penalty_rate_pct),
        penalty_cap_amount: num(rule.penalty_cap_amount),
        manager_name: str(rule.manager_name),
        manager_email: str(rule.manager_email) || str(cfg.cfg_default_manager_email),
        escalation_email: str(rule.escalation_email) || str(cfg.cfg_escalation_email),
        contract_start: str(rule.contract_start),
        contract_end: str(rule.contract_end),
        supplier_risk_tier: str(rule.supplier_risk_tier),
        breach_history: history.filter(h => str(h.supplier_id) === supplierId && str(h.metric_type).toLowerCase() === metric)
      }
    });
    continue;
  }

  result.push({
    json: {
      run_id: cfg.cfg_run_id,
      checked_at: cfg.cfg_checked_at,
      rule_id: str(rule.rule_id),
      supplier_id: supplierId,
      supplier_name: str(rule.supplier_name),
      metric_type: metric,
      data_status: 'ready',
      has_performance: true,
      sla_target: num(rule.sla_target),
      actual_value: num(latest.actual_value),
      unit: str(rule.unit),
      comparison_type: str(rule.comparison_type).toLowerCase(),
      penalty_clause: str(rule.penalty_clause),
      penalty_rate_pct: num(rule.penalty_rate_pct),
      penalty_cap_amount: num(rule.penalty_cap_amount),
      manager_name: str(rule.manager_name),
      manager_email: str(rule.manager_email) || str(cfg.cfg_default_manager_email),
      escalation_email: str(rule.escalation_email) || str(cfg.cfg_escalation_email),
      contract_start: str(rule.contract_start),
      contract_end: str(rule.contract_end),
      supplier_risk_tier: str(rule.supplier_risk_tier),
      record_id: str(latest.record_id),
      measurement_date: str(latest.measurement_date),
      po_number: str(latest.po_number),
      order_value: num(latest.order_value),
      notes: str(latest.notes),
      breach_history: history.filter(h => str(h.supplier_id) === supplierId && str(h.metric_type).toLowerCase() === metric)
    }
  });
}

return result;

const cfg = $items('Configure SLA Monitoring')[0]?.json || {};
const medium = Number(cfg.cfg_medium_deviation_pct || 5);
const high = Number(cfg.cfg_high_deviation_pct || 15);
const critical = Number(cfg.cfg_critical_deviation_pct || 25);

return $input.all().map(item => {
  const d = item.json || {};
  const target = Number(d.sla_target);
  const actual = Number(d.actual_value);
  const mode = String(d.comparison_type || '').toLowerCase();

  if (!d.has_performance || !Number.isFinite(target) || !Number.isFinite(actual) || target === 0) {
    return { json: {
      ...d,
      is_violation: false,
      compliance_status: 'NOT_EVALUATED',
      severity: 'none',
      severity_score: 0,
      deviation: null,
      deviation_percent: null,
      direction: '',
      evaluation_reason: d.has_performance ? 'Invalid SLA target or performance value.' : 'No matching supplier performance record was found.'
    }};
  }

  let isViolation = false;
  let deviation = 0;
  let direction = '';

  if (mode === 'min') {
    isViolation = actual < target;
    deviation = target - actual;
    direction = 'below_target';
  } else if (mode === 'max') {
    isViolation = actual > target;
    deviation = actual - target;
    direction = 'above_target';
  } else {
    return { json: {
      ...d,
      is_violation: false,
      compliance_status: 'NOT_EVALUATED',
      severity: 'none',
      severity_score: 0,
      deviation: null,
      deviation_percent: null,
      direction: '',
      evaluation_reason: 'comparison_type must be min or max.'
    }};
  }

  const deviationPercent = Number(((Math.abs(deviation) / Math.abs(target)) * 100).toFixed(2));
  let severity = 'none';
  let severityScore = 0;

  if (isViolation) {
    if (deviationPercent >= critical) { severity = 'critical'; severityScore = 4; }
    else if (deviationPercent >= high) { severity = 'high'; severityScore = 3; }
    else if (deviationPercent >= medium) { severity = 'medium'; severityScore = 2; }
    else { severity = 'low'; severityScore = 1; }
  }

  return { json: {
    ...d,
    is_violation: isViolation,
    compliance_status: isViolation ? 'NON_COMPLIANT' : 'COMPLIANT',
    severity,
    severity_score: severityScore,
    deviation: Number(deviation.toFixed(2)),
    deviation_percent: deviationPercent,
    direction,
    evaluation_reason: isViolation
      ? `Actual performance is ${direction.replace('_',' ')} by ${deviationPercent}%.`
      : 'Actual performance meets the configured SLA target.'
  }};
});

const items = $input.all().map(i => i.json || {});
const cfg = $items('Configure SLA Monitoring')[0]?.json || {};
const evaluated = items.filter(i => i.compliance_status === 'COMPLIANT' || i.compliance_status === 'NON_COMPLIANT');
const violations = evaluated.filter(i => i.is_violation === true);

return [{
  json: {
    run_id: cfg.cfg_run_id,
    checked_at: cfg.cfg_checked_at,
    total_records: items.length,
    evaluated_records: evaluated.length,
    compliant_count: evaluated.filter(i => i.compliance_status === 'COMPLIANT').length,
    violation_count: violations.length,
    critical_count: violations.filter(i => i.severity === 'critical').length,
    high_count: violations.filter(i => i.severity === 'high').length,
    medium_count: violations.filter(i => i.severity === 'medium').length,
    low_count: violations.filter(i => i.severity === 'low').length,
    not_evaluated_count: items.filter(i => i.compliance_status === 'NOT_EVALUATED').length,
    status: violations.length ? 'BREACHES_DETECTED' : 'ALL_CLEAR'
  }
}];

const cfg = $items('Configure SLA Monitoring')[0]?.json || {};
const lookbackDays = Math.max(0, Number(cfg.cfg_repeat_breach_lookback_days || 90));
const repeatThreshold = Math.max(1, Number(cfg.cfg_repeat_breach_threshold || 2));
const cutoff = Date.now() - lookbackDays * 86400000;

const str = v => v === null || v === undefined ? '' : String(v).trim();
const normDate = v => {
  const d = new Date(String(v || ''));
  return Number.isNaN(d.getTime()) ? str(v) : d.toISOString().slice(0,10);
};

return $input.all().map(item => {
  const d = item.json || {};
  const history = Array.isArray(d.breach_history) ? d.breach_history : [];
  const measurementDate = normDate(d.measurement_date);
  const breachKey = `${str(d.supplier_id)}|${str(d.metric_type).toLowerCase()}|${measurementDate}|${str(d.po_number)}`;

  const recentSameMetric = history.filter(h => {
    const dt = new Date(String(h.measurement_date || h.logged_at || ''));
    const validDate = !Number.isNaN(dt.getTime()) && dt.getTime() >= cutoff;
    return validDate &&
      str(h.supplier_id) === str(d.supplier_id) &&
      str(h.metric_type).toLowerCase() === str(d.metric_type).toLowerCase() &&
      String(h.status || '').toUpperCase() !== 'CANCELLED';
  });

  const duplicate = history.some(h => str(h.breach_key) === breachKey);
  const priorCount = recentSameMetric.length;

  return { json: {
    ...d,
    breach_key: breachKey,
    breach_id: `BRH-${str(d.supplier_id)}-${str(d.metric_type).slice(0,3).toUpperCase()}-${$execution.id}`,
    repeat_breach_count: priorCount,
    is_repeat_offender: priorCount >= repeatThreshold,
    is_new_breach: !duplicate,
    recent_breach_window_days: lookbackDays,
    days_until_contract_end: (() => {
      const end = new Date(String(d.contract_end || ''));
      return Number.isNaN(end.getTime()) ? null : Math.ceil((end.getTime() - Date.now()) / 86400000);
    })()
  }};
});

const cfg = $items('Configure SLA Monitoring')[0]?.json || {};

return $input.all().map(item => {
  const d = item.json || {};
  const orderValue = Number(d.order_value);
  const configuredRate = Number(d.penalty_rate_pct);
  const fallbackRate = Number(cfg.cfg_default_penalty_rate_pct || 2);
  const rate = Number.isFinite(configuredRate) && configuredRate >= 0 ? configuredRate : fallbackRate;
  const cap = Number(d.penalty_cap_amount);

  let suggestedPenalty = null;
  if (Number.isFinite(orderValue) && orderValue >= 0 && Number.isFinite(rate)) {
    suggestedPenalty = Number((orderValue * rate / 100).toFixed(2));
    if (Number.isFinite(cap) && cap > 0) suggestedPenalty = Math.min(suggestedPenalty, cap);
  }

  let enforcement = 'MONITOR';
  if (d.severity === 'critical' || d.is_repeat_offender) enforcement = 'ENFORCE_PENALTY';
  else if (d.severity === 'high') enforcement = 'REVIEW_AND_ENFORCE';
  else if (d.severity === 'medium') enforcement = 'CORRECTIVE_ACTION_FIRST';

  const requiresEscalation =
    ['high','critical'].includes(String(d.severity)) ||
    d.is_repeat_offender === true;

  let escalationLevel = 'Supplier Manager';
  if (d.severity === 'critical') escalationLevel = 'Procurement Director';
  else if (requiresEscalation) escalationLevel = 'Procurement Manager';

  const due = new Date();
  due.setDate(due.getDate() + Number(cfg.cfg_action_due_days || 30));

  return { json: {
    ...d,
    applied_penalty_rate_pct: rate,
    suggested_penalty_amount: suggestedPenalty,
    enforcement_recommendation: enforcement,
    requires_escalation: requiresEscalation,
    escalation_level: escalationLevel,
    corrective_action_due_date: due.toISOString().slice(0,10)
  }};
});

const aggregate = $items('Aggregate New Violations')[0]?.json || {};
const violations = Array.isArray(aggregate.violations) ? aggregate.violations : [];
const raw = String($json.text || '').replace(/```json|```/g, '').trim();

let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }

const recs = Array.isArray(parsed.recommendations) ? parsed.recommendations : [];
const str = v => v === null || v === undefined ? '' : String(v).trim();
const listText = v => Array.isArray(v) ? v.map(str).filter(Boolean).join(' | ') : str(v);

return violations.map(v => {
  const rec = recs.find(r => str(r.breach_id) === str(v.breach_id)) || {};
  const fallbackAction = `${v.enforcement_recommendation}: review ${v.metric_type} performance with ${v.supplier_name} and agree a corrective action plan.`;

  return { json: {
    run_id: aggregate.run_id || '',
    breach_id: v.breach_id || '',
    supplier_id: v.supplier_id || '',
    supplier_name: v.supplier_name || '',
    metric_type: v.metric_type || '',
    severity: v.severity || '',
    repeat_breach_count: v.repeat_breach_count ?? 0,
    is_repeat_offender: v.is_repeat_offender === true,
    sla_target: v.sla_target ?? '',
    actual_value: v.actual_value ?? '',
    unit: v.unit || '',
    deviation_percent: v.deviation_percent ?? '',
    penalty_clause: v.penalty_clause || '',
    suggested_penalty_amount: v.suggested_penalty_amount ?? '',
    enforcement_recommendation: v.enforcement_recommendation || '',
    escalation_level: v.escalation_level || '',
    requires_escalation: ['high','critical'].includes(String(v.severity)) || v.is_repeat_offender === true,
    po_number: v.po_number || '',
    manager_name: v.manager_name || '',
    manager_email: v.manager_email || '',
    escalation_email: v.escalation_email || '',
    corrective_action_due_date: v.corrective_action_due_date || '',
    root_cause_assessment: str(rec.root_cause_assessment) || 'Root cause requires supplier confirmation.',
    immediate_actions: listText(rec.immediate_actions) || 'Contact supplier and validate the cause of the SLA deviation.',
    penalty_recommendation: str(rec.penalty_recommendation) || v.enforcement_recommendation || '',
    corrective_action_plan: listText(rec.corrective_action_plan) || fallbackAction,
    escalation_path: str(rec.escalation_path) || v.escalation_level || '',
    supplier_risk_rating: str(rec.supplier_risk_rating) || v.supplier_risk_tier || v.severity || '',
    recommended_action: str(rec.recommended_action) || fallbackAction,
    status: 'OPEN',
    created_at: aggregate.checked_at || new Date().toISOString()
  }};
});

return $input.all().map(item => {
  const d = item.json || {};
  const penalty = d.suggested_penalty_amount === '' || d.suggested_penalty_amount === null || d.suggested_penalty_amount === undefined
    ? 'Not calculated'
    : String(d.suggested_penalty_amount);

  const subjectPrefix = d.severity === 'critical' ? 'CRITICAL' : String(d.severity || 'SLA').toUpperCase();
  const html = `
  <div style="font-family:Arial,sans-serif;max-width:720px;margin:auto">
    <h2>Supplier SLA Breach - ${d.supplier_name}</h2>
    <p><strong>Severity:</strong> ${String(d.severity || '').toUpperCase()}</p>
    <p><strong>Metric:</strong> ${d.metric_type}<br>
    <strong>Target:</strong> ${d.sla_target} ${d.unit}<br>
    <strong>Actual:</strong> ${d.actual_value} ${d.unit}<br>
    <strong>Deviation:</strong> ${d.deviation_percent}%</p>
    <p><strong>Repeat breaches in lookback window:</strong> ${d.repeat_breach_count}</p>
    <p><strong>Deterministic enforcement recommendation:</strong> ${d.enforcement_recommendation}<br>
    <strong>Suggested penalty amount:</strong> ${penalty}</p>
    <h3>Recommended Action</h3>
    <p>${d.recommended_action}</p>
    <h3>Immediate Actions</h3>
    <p>${d.immediate_actions}</p>
    <h3>Corrective Action Plan</h3>
    <p>${d.corrective_action_plan}</p>
    <p><strong>Action due date:</strong> ${d.corrective_action_due_date}</p>
    <p style="font-size:12px;color:#666">Breach ID: ${d.breach_id}</p>
  </div>`;

  return { json: {
    ...d,
    email_to: d.manager_email || '',
    email_subject: `${subjectPrefix}: SLA breach ${d.breach_id} - ${d.supplier_name}`,
    email_body: html
  }};
});

return $input.all().map(item => {
  const d = item.json || {};
  const html = `
  <div style="font-family:Arial,sans-serif;max-width:720px;margin:auto">
    <h2>Procurement Escalation - Supplier SLA Breach</h2>
    <p><strong>Supplier:</strong> ${d.supplier_name} (${d.supplier_id})</p>
    <p><strong>Severity:</strong> ${String(d.severity || '').toUpperCase()}</p>
    <p><strong>Repeat offender:</strong> ${d.is_repeat_offender ? 'Yes' : 'No'} (${d.repeat_breach_count} prior breach(es) in lookback window)</p>
    <p><strong>Metric:</strong> ${d.metric_type} | <strong>Deviation:</strong> ${d.deviation_percent}%</p>
    <p><strong>Enforcement recommendation:</strong> ${d.enforcement_recommendation}</p>
    <p><strong>Suggested penalty:</strong> ${d.suggested_penalty_amount === '' ? 'Not calculated' : d.suggested_penalty_amount}</p>
    <p><strong>Escalation level:</strong> ${d.escalation_level}</p>
    <h3>Gemini Corrective Action Recommendation</h3>
    <p>${d.recommended_action}</p>
    <p style="font-size:12px;color:#666">Breach ID: ${d.breach_id}</p>
  </div>`;

  return { json: {
    ...d,
    escalation_to: d.escalation_email || '',
    escalation_subject: `ESCALATION: ${String(d.severity || '').toUpperCase()} SLA breach - ${d.supplier_name}`,
    escalation_body: html
  }};
});
